package br.com.sistemacardapio.promocao;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/promocoes")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class PromocaoController{private final PromocaoService s;public PromocaoController(PromocaoService s){this.s=s;}@GetMapping public List<PromocaoService.Response>listar(){return s.listar();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public PromocaoService.Response criar(@Valid@RequestBody PromocaoService.Request r){return s.criar(r);}@PutMapping("/{id}")public PromocaoService.Response atualizar(@PathVariable UUID id,@Valid@RequestBody PromocaoService.Request r){return s.atualizar(id,r);}}
